"""Helpers that write the generated MyST pages.

Docstrings in this project are reStructuredText, so generated pages wrap
them, and every table that holds docstring text, in ``{eval-rst}`` blocks.
"""

import inspect
import re
from pathlib import Path

FENCE = "````"

_SENTENCE_END = re.compile(r"\.\s+(?=[A-Z(`*])")


GENERATED_MARK = "<!-- Generated by docs/_ext/assets_docs"


def generated_note(sources):
    """The comment that opens every generated page."""
    names = ", ".join(sources)
    return (
        f"{GENERATED_MARK} from {names}. "
        "Do not edit: the file is rewritten on every build. -->\n"
    )


def lines_note(linemap):
    """A comment holding the source lines of a page's objects.

    sphinx.ext.linkcode puts the lines into the [source] links when a page is
    read; with them in the text, a change of lines alone re-reads the page.
    """
    return "<!-- source lines: " + " ".join(
        f"{name}:{line}" for name, (_, line) in linemap.items()) + " -->\n"


def eval_rst(text):
    """A MyST ``{eval-rst}`` block holding ``text``."""
    return f"{FENCE}{{eval-rst}}\n{text.rstrip()}\n{FENCE}\n"


def clean(doc):
    """A docstring without its common indentation, or ``""``."""
    return inspect.cleandoc(doc) if doc else ""


def indent(text, n=3):
    pad = " " * n
    return "\n".join(pad + line if line.strip() else "" for line in text.splitlines())


def _balanced(text):
    return (
        text.count("``") % 2 == 0
        and text.replace("``", "").count("`") % 2 == 0
        and text.count("**") % 2 == 0
        and text.replace("**", "").count("*") % 2 == 0
    )


def summary(doc, limit=200):
    """The first paragraph of a docstring on one line.

    A paragraph longer than ``limit`` is cut after its first sentence, where
    the cut leaves the inline markup balanced.
    """
    para = clean(doc).split("\n\n", 1)[0]
    line = " ".join(part.strip() for part in para.splitlines()).strip()
    if line.endswith("::"):
        line = line[:-1]
    if len(line) > limit:
        for m in _SENTENCE_END.finditer(line):
            head = line[: m.start() + 1]
            if _balanced(head):
                return head
    return line


def literal(text):
    """``text`` as an RST inline literal."""
    text = str(text)
    if not text.strip():
        return "(blank)"
    return f"``{text}``"


def link(text, url):
    """An anonymous RST hyperlink, or ``text`` as a literal if there is no URL."""
    return f"`{text} <{url}>`__" if url else literal(text)


def md_link(text, url):
    """A Markdown link with code text, or the code text if there is no URL."""
    return f"[`{text}`]({url})" if url else f"`{text}`"


def list_table(header, rows, widths=None, cls=None):
    """An RST ``list-table``; a cell is RST text and may span lines."""
    out = [".. list-table::", "   :header-rows: 1"]
    if widths:
        out.append("   :widths: " + " ".join(str(w) for w in widths))
    if cls:
        out.append(f"   :class: {cls}")
    out.append("")
    for row in [header, *rows]:
        for i, cell in enumerate(row):
            lead = "   * -" if i == 0 else "     -"
            lines = str(cell).splitlines() if cell else []
            if not lines:
                out.append(lead)
                continue
            out.append(f"{lead} {lines[0]}")
            out.extend(f"       {line}" if line.strip() else "" for line in lines[1:])
    return "\n".join(out)


def field_table(rows):
    """A two-column table of facts, the first column a stub."""
    out = [".. list-table::", "   :stub-columns: 1", "   :widths: 20 80", "   :class: assets-facts", ""]
    for name, value in rows:
        out.append(f"   * - {name}")
        out.append(f"     - {value}")
    return "\n".join(out)


def write_pages(out_dir, pages, logger=None):
    """Write ``pages`` ({relative path: text}) under ``out_dir``.

    A file is written only when its text changed, so that Sphinx re-reads
    only the pages that changed. Generated Markdown files under ``out_dir``
    that are not in ``pages`` are deleted; other files are left alone.
    """
    out_dir = Path(out_dir)
    keep = set()
    for rel, text in pages.items():
        path = out_dir / rel
        keep.add(path.resolve())
        if path.exists() and path.read_text(encoding="utf-8") == text:
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
        if logger:
            logger.info(f"[assets_docs] wrote {path.relative_to(out_dir.parent).as_posix()}")
    if out_dir.exists():
        for path in list(out_dir.rglob("*.md")):
            if path.resolve() in keep:
                continue
            with path.open(encoding="utf-8", errors="replace") as f:
                generated = f.read(len(GENERATED_MARK)) == GENERATED_MARK
            if generated:  # after closing it: Windows cannot delete an open file
                path.unlink()
